<?php
$page_title='ศูนย์ผู้ขาย';require_once __DIR__.'/includes/auth_check.php';requireSeller();require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/image_upload.php';require_once __DIR__.'/includes/security_monitor.php';$db=(new Database())->getConnection();$sellerId=(int)$_SESSION['user_id'];$message=$error='';
$q=$db->prepare("SELECT * FROM seller_profiles WHERE user_id=? AND status='approved'");$q->execute([$sellerId]);$store=$q->fetch();if(!$store){header('Location: '.BASE_URL.'seller.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);try{if($store['store_status']!=='active'||!(int)$store['product_submission_enabled'])throw new RuntimeException('ร้านถูกจำกัดการเพิ่มสินค้า');$name=trim((string)($_POST['name']??''));$category=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock_quantity']??0);if(mb_strlen($name)<2||$category<1||$price<=0||$stock<0)throw new RuntimeException('กรุณากรอกข้อมูลสินค้าให้ครบ');$image=saveProductImageUpload($_FILES['product_image']??[]);$db->prepare("INSERT INTO products(category_id,seller_id,name,description,price,stock_quantity,image_url,is_featured,approval_status) VALUES(?,?,?,?,?,?,?,0,'pending')")->execute([$category,$sellerId,$name,trim((string)($_POST['description']??'')),$price,$stock,$image]);$id=(int)$db->lastInsertId();$db->prepare("INSERT INTO inventory_movements(seller_id,product_id,movement_type,quantity_change,quantity_before,quantity_after,note,created_by) VALUES(?,?,'initial',?,0,?,'สต็อกเริ่มต้น',?)")->execute([$sellerId,$id,$stock,$stock,$sellerId]);createRoleNotification($db,'admin','seller','มีสินค้าใหม่รอตรวจสอบ','สินค้า '.$name.' รอตรวจสอบ',BASE_URL.'admin/seller-products.php');$message='ส่งสินค้าเข้าตรวจสอบแล้ว';}catch(Throwable $e){$error=$e->getMessage();}}
$categories=$db->query('SELECT id,name FROM categories ORDER BY id')->fetchAll();$q=$db->prepare("SELECT COUNT(*) products,SUM(approval_status='pending') pending,SUM(stock_quantity<=5) low_stock FROM products WHERE seller_id=?");$q->execute([$sellerId]);$product=$q->fetch();$q=$db->prepare("SELECT COUNT(DISTINCT o.id) orders,COALESCE(SUM(oi.subtotal),0) revenue,COUNT(DISTINCT CASE WHEN COALESCE(f.status,'pending')='pending' AND o.created_at<DATE_SUB(NOW(),INTERVAL 24 HOUR) THEN o.id END) late FROM orders o JOIN order_items oi ON oi.order_id=o.id LEFT JOIN order_fulfillments f ON f.order_id=o.id AND f.seller_id=? WHERE oi.seller_id=? AND o.order_status<>'cancelled' AND o.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)");$q->execute([$sellerId,$sellerId]);$order=$q->fetch();$q=$db->prepare('SELECT COALESCE(AVG(r.rating),0) rating FROM product_reviews r JOIN products p ON p.id=r.product_id WHERE p.seller_id=?');$q->execute([$sellerId]);$rating=(float)$q->fetchColumn();$q=$db->prepare("SELECT COALESCE(SUM(points),0) FROM seller_strikes WHERE seller_id=? AND status='active' AND (expires_at IS NULL OR expires_at>NOW())");$q->execute([$sellerId]);$points=(int)$q->fetchColumn();$score=max(0,100-$points*10-(int)$order['late']*5);$tier=$score>=90?'ยอดเยี่ยม':($score>=75?'มาตรฐาน':'ต้องปรับปรุง');$q=$db->prepare("SELECT o.order_no,o.created_at,SUM(oi.subtotal) total,COALESCE(f.status,'pending') status FROM orders o JOIN order_items oi ON oi.order_id=o.id LEFT JOIN order_fulfillments f ON f.order_id=o.id AND f.seller_id=? WHERE oi.seller_id=? GROUP BY o.id,f.status ORDER BY o.id DESC LIMIT 5");$q->execute([$sellerId,$sellerId]);$recent=$q->fetchAll();require_once __DIR__.'/includes/header.php';?>
<link rel="stylesheet" href="<?php echo BASE_URL;?>assets/css/seller.css"><main id="main-content" class="seller-page"><div class="container"><?php require __DIR__.'/includes/seller_nav.php';?><section class="seller-hero seller-dashboard-hero"><div><p class="eyebrow">SELLER OPERATIONS</p><h1><?php echo e($store['shop_name']);?></h1><p>งานสำคัญ ยอดขาย คุณภาพร้าน และคลังสินค้าอยู่ในหน้าเดียว</p></div><aside><span><i class="fa-solid fa-award"></i></span><strong>ระดับร้าน <?php echo e($tier);?></strong><div class="seller-progress"><span style="width:<?php echo $score;?>%"></span></div><small>คะแนน <?php echo $score;?>/100</small></aside></section><?php if($message):?><p class="seller-success"><?php echo e($message);?></p><?php endif;?><?php if($error):?><p class="seller-error"><?php echo e($error);?></p><?php endif;?><section class="seller-ops-grid"><div class="seller-ops-card"><small>ยอดขาย 30 วัน</small><strong><?php echo formatCurrency($order['revenue']);?></strong></div><div class="seller-ops-card"><small>ออเดอร์ 30 วัน</small><strong><?php echo (int)$order['orders'];?></strong></div><div class="seller-ops-card"><small>คะแนนรีวิว</small><strong><?php echo number_format($rating,1);?></strong></div><div class="seller-ops-card"><small>สินค้าใกล้หมด</small><strong><?php echo (int)$product['low_stock'];?></strong></div></section><section class="seller-alert-list"><?php if((int)$order['late']):?><a class="seller-alert" href="seller-orders.php"><span>มี <?php echo (int)$order['late'];?> ออเดอร์รอรับเกิน 24 ชั่วโมง</span><strong>จัดการ →</strong></a><?php endif;?><?php if((int)$product['low_stock']):?><a class="seller-alert" href="seller-inventory.php?stock=low"><span>สินค้าใกล้หมด <?php echo (int)$product['low_stock'];?> รายการ</span><strong>เติมสต็อก →</strong></a><?php endif;?></section><section class="admin-panel"><header class="admin-panel-header"><div><h2>ออเดอร์ล่าสุด</h2><p>งานจัดส่งที่ต้องติดตาม</p></div><a class="btn btn-outline" href="seller-orders.php">ดูทั้งหมด</a></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ออเดอร์</th><th>วันที่</th><th>ยอดร้าน</th><th>สถานะ</th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="4" class="admin-empty">ยังไม่มีออเดอร์</td></tr><?php endif;?><?php foreach($recent as $o):?><tr><td><strong><?php echo e($o['order_no']);?></strong></td><td><?php echo date('d/m/Y H:i',strtotime($o['created_at']));?></td><td><?php echo formatCurrency($o['total']);?></td><td><span class="status-badge pending"><?php echo e($o['status']);?></span></td></tr><?php endforeach;?></tbody></table></div></section><section class="seller-application seller-dashboard"><aside><p class="eyebrow">QUICK ADD</p><h2>เพิ่มสินค้า</h2><p>สินค้าใหม่จะรอแอดมินตรวจสอบ</p></aside><form class="seller-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><div class="seller-fields"><label class="full">ชื่อสินค้า<input name="name" required maxlength="200"></label><label>หมวด<select name="category_id"><?php foreach($categories as $c):?><option value="<?php echo $c['id'];?>"><?php echo e($c['name']);?></option><?php endforeach;?></select></label><label>ราคา<input type="number" name="price" min=".01" step=".01" required></label><label>สต็อก<input type="number" name="stock_quantity" min="0" required></label><label class="full">รูป<input type="file" name="product_image" accept="image/jpeg,image/png,image/webp" required></label><label class="full">รายละเอียด<textarea name="description"></textarea></label></div><footer><span>จะขึ้นขายหลังอนุมัติ</span><button class="btn btn-primary">ส่งเข้าตรวจ</button></footer></form></section></div></main><?php require_once __DIR__.'/includes/footer.php';?>
